import React from "react";
import { NavLink } from "react-router-dom";

const Sidebar = () => {
  return (
    <div className="min-h-screen flex">
      <aside className="flex flex-col justify-between w-64 bg-gray-900 dark:bg-background-dark border-r border-green-200 dark:border-gray-700 p-4">
        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <NavLink
              to="/Userdashboad"
              className={({ isActive }) =>
                `flex items-center gap-3 px-3 py-2 rounded-lg transition-all ${
                  isActive
                    ? "bg-green-200 text-green-700 dark:bg-green-600 dark:text-white"
                    : "hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300"
                }`
              }
            >
              <span className="material-symbols-outlined">add_circle</span>
              <p className="text-sm font-medium">Submit New Report</p>
            </NavLink>

            <NavLink
              to="/Reporthistory"
              className={({ isActive }) =>
                `flex items-center gap-3 px-3 py-2 rounded-lg transition-all ${
                  isActive
                    ? "bg-green-200 text-green-700 dark:bg-green-700 dark:text-white"
                    : "hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300"
                }`
              }
            >
              <span className="material-symbols-outlined">history</span>
              <p className="text-sm font-medium">Report History</p>
            </NavLink>
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <button className="flex w-full items-center justify-center gap-2 rounded-lg h-10 px-4 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-white text-sm font-medium">
            <span className="material-symbols-outlined">logout</span>
            <span className="truncate">Logout</span>
          </button>
        </div>
      </aside>
    </div>
  );
};

export default Sidebar;
